<?php require_once __DIR__.'/../app/layout.php';$type=($_GET['type']??$_POST['type']??'member')==='admin'?'admin':'member';$token=$_GET['token']??$_POST['token']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$password=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM password_resets WHERE account_type=? AND token_hash=? AND used_at IS NULL AND expires_at>NOW() ORDER BY id DESC LIMIT 1');$s->execute([$type,hash('sha256',$token)]);$row=$s->fetch();if(!$row||strlen($password)<8){flash('The link is invalid, expired, or the password is too short.','error');}else{$table=$type==='admin'?'admins':'members';$pdo->prepare("UPDATE {$table} SET password_hash=? WHERE email=?")->execute([password_hash($password,PASSWORD_DEFAULT),$row['email']]);$pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$row['id']]);flash('Password updated. Please sign in.');redirect($type==='admin'?'/admin/login.php':'/login.php');}}header_html('Reset password');?><h1>Reset password</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="<?=e($type)?>"><input type="hidden" name="token" value="<?=e($token)?>"><label>New password<input type="password" name="password" minlength="8" required></label><button>Update password</button></form><?php footer_html();
